import{_ as t,c as d,o as r,V as a}from"./chunks/framework.tJhZUYt7.js";const f=JSON.parse('{"title":"二、注释和关键字","description":"","frontmatter":{},"headers":[],"relativePath":"rear/java/Java基础语法/注释和关键字.md","filePath":"rear/java/Java基础语法/注释和关键字.md","lastUpdated":1719821588000}'),e={name:"rear/java/Java基础语法/注释和关键字.md"},o=a('<h1 id="二、注释和关键字" tabindex="-1">二、注释和关键字 <a class="header-anchor" href="#二、注释和关键字" aria-label="Permalink to &quot;二、注释和关键字&quot;">​</a></h1><h2 id="一、注释" tabindex="-1">一、注释 <a class="header-anchor" href="#一、注释" aria-label="Permalink to &quot;一、注释&quot;">​</a></h2><h3 id="_1、注释分类" tabindex="-1">1、注释分类 <a class="header-anchor" href="#_1、注释分类" aria-label="Permalink to &quot;1、注释分类&quot;">​</a></h3><p>注释分类有三种：</p><ol><li><code>单行注释</code> 格式：//注释信息</li><li><code>多行注释</code> 格式：/*注释信息*/</li><li><code>文档注释</code> 格式：/**注释信息*/</li></ol><h2 id="二、关键字" tabindex="-1">二、关键字 <a class="header-anchor" href="#二、关键字" aria-label="Permalink to &quot;二、关键字&quot;">​</a></h2><h3 id="_1、什么是关键字" tabindex="-1">1、什么是关键字 <a class="header-anchor" href="#_1、什么是关键字" aria-label="Permalink to &quot;1、什么是关键字&quot;">​</a></h3><blockquote><p>被Java赋予了特定含义的英文单词</p></blockquote><h3 id="_2、关键词的特点" tabindex="-1">2、关键词的特点 <a class="header-anchor" href="#_2、关键词的特点" aria-label="Permalink to &quot;2、关键词的特点&quot;">​</a></h3><ul><li>关键字的字母全部小写</li><li>常用的代码编辑器，对关键字有特殊颜色标记</li></ul><h3 id="_3、关键字列表" tabindex="-1">3、关键字列表 <a class="header-anchor" href="#_3、关键字列表" aria-label="Permalink to &quot;3、关键字列表&quot;">​</a></h3><table><thead><tr><th>关键字</th><th>说明</th></tr></thead><tbody><tr><td>abstract</td><td>表明类或者成员方法具有抽象属性</td></tr><tr><td>assert</td><td>断言，用来进行程序调试</td></tr><tr><td>boolean</td><td>布尔类型，基本数据类型之一</td></tr><tr><td>bréak</td><td>提前跳出一个块</td></tr><tr><td>byte</td><td>字节类型，基本数据类型之一</td></tr><tr><td>case</td><td>用于switch语句之中，表示其中的一个分支</td></tr><tr><td>catch</td><td>用于异常处理中，用来捕获异常</td></tr><tr><td>char</td><td>字符类型，基本数据类型之一</td></tr><tr><td>cláss</td><td>声明一个类</td></tr><tr><td>const</td><td>保留关键字，没有具体含义</td></tr><tr><td>continue</td><td>回到一个块的开始处</td></tr><tr><td>default</td><td>默认。例如，用于switch语句中，表明一个默认的分支</td></tr><tr><td>do</td><td>用于do-while循环结构中</td></tr><tr><td>double</td><td>双精度浮点数类型，基本数据类型之一</td></tr><tr><td>else</td><td>用于条件语句中，表明当条件不成立时的分支</td></tr><tr><td>enum</td><td>枚举类型</td></tr><tr><td>extends</td><td>表明一个类型是另一个类型的子类型，这里常见的类型有类和接口</td></tr><tr><td>final</td><td>用来说明最终属性，表明一个类不能派生出子类，或者成员方法不能被覆盖，或者成员域的值不能被改变，用来定义常量</td></tr><tr><td>finally</td><td>用于处理异常情况，用来声明一个基本肯定会被执行的语句块</td></tr><tr><td>float</td><td>单精度浮点数类型，基本数据类型之一</td></tr><tr><td>for</td><td>用于循环体中，表示循环初始条件和判断条件</td></tr><tr><td>goto</td><td>保留关键字，没有具体含义</td></tr><tr><td>if</td><td>条件语句的引导词</td></tr><tr><td>implements</td><td>表明一个类实现了给定的接口</td></tr><tr><td>import</td><td>表明要访问指定的类或包</td></tr><tr><td>instanceof</td><td>用来测试一个对象是否是指定类型的实例对象</td></tr><tr><td>int</td><td>整数类型，基本数据类型之一</td></tr><tr><td>interface</td><td>接口</td></tr><tr><td>long</td><td>长整数类型，基本数据类型之一</td></tr><tr><td>native</td><td>用来声明一个方法是由与计算机相关的语言实现的</td></tr><tr><td>new</td><td>声明新的实例对象</td></tr><tr><td>package</td><td>包声明</td></tr><tr><td>private</td><td>私有访问模式</td></tr><tr><td>protected</td><td>继承访问模式</td></tr><tr><td>public</td><td>公开访问模式</td></tr><tr><td>return</td><td>从成员方法中返回数据</td></tr><tr><td>short</td><td>短整数类型，基本数据类型之一</td></tr><tr><td>static</td><td>表明具有静态属性</td></tr><tr><td>strictfp</td><td>用来声明单精度或双精度浮点数表达式遵循IEEE754算术规范</td></tr><tr><td>super</td><td>表明当前对象的父类型的引用或者父类型的构造方法</td></tr><tr><td>switch</td><td>分支语句结构的引导词</td></tr><tr><td>synchronized</td><td>表明一段代码需要同步执行</td></tr><tr><td>this</td><td>指向当前实例对象的引用</td></tr><tr><td>throw</td><td>抛出一个异常</td></tr><tr><td>throws</td><td>声明在当前定义的成员方法中所有需要抛出的异常</td></tr><tr><td>transient</td><td>声明不用序列化的成员域</td></tr><tr><td>try</td><td>尝试一个可能抛出异常的程序块</td></tr><tr><td>void</td><td>声明当前成员方法没有返回值</td></tr><tr><td>volatile</td><td>表明两个或者多个变量必须同步地发生变化</td></tr><tr><td>while</td><td>用于循环结构中，表示循环条件</td></tr></tbody></table>',12),i=[o];function l(c,n,h,s,_,u){return r(),d("div",null,i)}const p=t(e,[["render",l]]);export{f as __pageData,p as default};
